.guide-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.guide-card-img {
  width: 100%;
  height: 160px;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
