  margin-right: auto;
}
.hero-actions {
  margin-top: 28px;
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  border-radius: 980px;
  font-size: 16px;
  font-weight: 500;
  letter-spacing: -0.01em;
  cursor: pointer;
  border: none;
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--color-accent);
  color: var(--color-white);
}
.btn-primary:hover { background: #0055aa; }
.btn-outline {
  background: transparent;
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
}
.btn-outline:hover { background: var(--color-accent); color: var(--color-white); }
.btn-ghost {
  background: transparent;
  color: var(--color-accent);
  padding: 8px 16px;
}
.btn-ghost:hover { text-decoration: underline; }

/* --- Product Icon Bar --- */
.icon-bar {
  padding: 0;
  border-bottom: 1px solid var(--color-border);
}
.icon-bar-track {
  display: flex;
  gap: 0;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0 16px;
}
.icon-bar-track::-webkit-scrollbar { display: none; }
.icon-bar-item {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 14px;
  scroll-snap-align: start;
  cursor: pointer;
  transition: opacity var(--transition);
  min-width: 72px;
}
.icon-bar-item:hover { opacity: 0.7; }
.icon-bar-item .icon-circle {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 6px;
  font-size: 20px;
}
.icon-bar-item span {
  font-size: 11px;
  font-weight: 500;
  color: var(--color-primary);
  letter-spacing: -0.01em;
}

/* --- Carousels --- */
.carousel { position: relative; }
.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 4px 0 16px;
}
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-card {
  flex: 0 0 auto;
  scroll-snap-align: start;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: var(--color-primary);
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  opacity: 0.9;
}
.carousel-btn:hover { opacity: 1; box-shadow: var(--shadow-md); }
.carousel-btn:active { transform: translateY(-50%) scale(0.95); }
.carousel-btn:disabled { opacity: 0; pointer-events: none; }
.carousel-prev { left: -8px; }
.carousel-next { right: -8px; }

/* --- Product Card (carousel) --- */
.product-card {
  width: 280px;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
}
.product-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.product-card-img {
  width: 100%;
  height: 200px;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 60px;
}
.product-card-body { padding: 16px 20px 20px; }
.product-card-body h3 { font-size: 17px; font-weight: 600; margin-bottom: 2px; }
.product-card-body .tagline { font-size: 14px; color: var(--color-text-secondary); margin-bottom: 8px; }
.product-card-body .price { font-size: 14px; font-weight: 500; color: var(--color-primary); }
.product-card-body .monthly { font-size: 12px; color: var(--color-text-secondary); margin-top: 2px; }
.product-card .badge-new {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--color-primary);
  color: var(--color-white);
  font-size: 10px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 4px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  z-index: 2;
}

/* --- Product Card Large (homepage tiles) --- */
.product-tile {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition), box-shadow var(--transition);
  min-height: 500px;
}
.product-tile:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); }
.product-tile-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 24px;
  text-align: center;
  z-index: 1;
}
.product-tile-content h3 {
  font-size: clamp(28px, 3.5vw, 40px);
  font-weight: 700;
  margin-bottom: 6px;
  letter-spacing: -0.003em;
}
.product-tile-content p {
  font-size: 17px;
  color: var(--color-text-secondary);
  max-width: 300px;
  margin-bottom: 20px;
}
.product-tile-actions { display: flex; gap: 16px; flex-wrap: wrap; justify-content: center; }
.product-tile-img {
  width: 100%;
  height: 240px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 80px;
}

/* Tile color variants */
.tile-dark { background: var(--color-primary); color: var(--color-white); }
.tile-dark p { color: rgba(255,255,255,0.7); }
.tile-dark .btn-outline { color: var(--color-white); border-color: var(--color-white); }
.tile-dark .btn-outline:hover { background: var(--color-white); color: var(--color-primary); }
.tile-warm { background: linear-gradient(135deg, #fce4d6, #f8cbad); }
.tile-cool { background: linear-gradient(135deg, #dbeafe, #c7d2fe); }
.tile-teal { background: linear-gradient(135deg, #ccfbf1, #99f6e4); }
.tile-rose { background: linear-gradient(135deg, #fce7f3, #fbcfe8); }
.tile-blue { background: linear-gradient(135deg, #dbeafe, #93c5fd); }

/* --- Tab System --- */
.tabs-nav {
  display: flex;
  gap: 4px;
  justify-content: center;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.tab-btn {
  padding: 10px 20px;
  border-radius: 980px;
  border: none;
  background: transparent;
  color: var(--color-text-secondary);
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  font-family: var(--font-stack);
}
.tab-btn:hover { background: rgba(0,0,0,0.04); color: var(--color-primary); }
.tab-btn.active { background: var(--color-primary); color: var(--color-white); }
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* --- Entertainment Card --- */
.ent-card {
  width: 220px;
  background: var(--color-white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  cursor: pointer;
}
.ent-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.ent-card-img {
  width: 100%;
  height: 280px;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
}
.ent-card-body { padding: 14px 16px 16px; }
.ent-card-body h4 { font-size: 15px; font-weight: 600; margin-bottom: 2px; }
.ent-card-body p { font-size: 13px; color: var(--color-text-secondary); }
.ent-card-body .cta {
  display: inline-block;
  margin-top: 8px;
  font-size: 13px;
  font-weight: 500;
  color: var(--color-accent);
}

/* --- Help / Store Diff / Guide Cards --- */
.info-card {
  width: 280px;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  flex-shrink: 0;
}
.info-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.info-card .icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 16px;
}
.info-card h4 { font-size: 17px; font-weight: 600; margin-bottom: 6px; }
.info-card p { font-size: 14px; color: var(--color-text-secondary); line-height: 1.5; }

/* --- Audio Promo Banner --- */
.promo-banner {
  background: var(--color-bg);
  border-radius: var(--radius-lg);
  padding: 24px 32px;
  margin-bottom: 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}
.promo-banner p { font-size: 15px; color: var(--color-primary); }

/* --- Brand Collab --- */
.brand-collab {
  background: linear-gradient(135deg, #1a1a2e, #16213e);
  color: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 60px 40px;
  display: flex;
  align-items: center;
  gap: 60px;
  flex-wrap: wrap;
}
.brand-collab h3 {
  font-size: clamp(28px, 4vw, 40px);
  font-weight: 700;
  margin-bottom: 12px;
}
.brand-collab p { font-size: 17px; opacity: 0.8; max-width: 400px; }
.brand-collab .collab-img {
  font-size: 100px;
  flex-shrink: 0;
}

/* --- Quick Links --- */
.quick-links {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.quick-link {
  padding: 14px 24px;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 980px;
  font-size: 15px;
  font-weight: 500;
  color: var(--color-primary);
  cursor: pointer;
  transition: all var(--transition);
}
.quick-link:hover { background: var(--color-bg); border-color: var(--color-primary); }

/* --- Sticky Section Nav --- */
.section-nav {
  position: sticky;
  top: 52px;
  z-index: 50;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
}
.section-nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  gap: 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.section-nav-inner::-webkit-scrollbar { display: none; }
.section-nav-link {
  padding: 14px 20px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  white-space: nowrap;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
  font-family: var(--font-stack);
}
.section-nav-link:hover { color: var(--color-primary); }
.section-nav-link.active {
  color: var(--color-primary);
  border-bottom-color: var(--color-primary);
}

/* --- Footer --- */
.footer {
  background: var(--color-bg);
  padding: 56px 0 32px;
  font-size: 12px;
  color: var(--color-text-secondary);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px;
  padding-bottom: 32px;
  border-bottom: 1px solid var(--color-border);
}
.footer-col h5 {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-primary);
  margin-bottom: 10px;
  cursor: default;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 6px; }
.footer-col a {
  font-size: 12px;
  color: var(--color-text-secondary);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--color-primary); text-decoration: underline; }
.footer-bottom {
  padding-top: 24px;
  font-size: 12px;
  line-height: 1.6;
}
.footer-bottom p { margin-bottom: 8px; }
.footer-bottom a { color: var(--color-accent); }

/* Mobile footer accordion */
.footer-col-toggle {
  display: none;
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  padding: 10px 0;
  cursor: pointer;
  font-size: 12px;
  font-weight: 600;
  color: var(--color-primary);
  font-family: var(--font-stack);
}
.footer-col-toggle::after {
  content: '+';
  float: right;
  font-size: 14px;
  transition: transform var(--transition);
}
.footer-col-toggle.open::after { content: '−'; }

/* --- Category Hero --- */
.category-hero {
  background: var(--color-bg);
  padding: 60px 0;
  text-align: center;
}
.category-hero h1 {
  font-size: clamp(40px, 5vw, 56px);
  font-weight: 700;
  letter-spacing: -0.005em;
}

/* --- Shopping Guides --- */
.guide-card {
  width: 280px;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  flex-shrink: 0;
  cursor: pointer;
}
.guide-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.guide-card-img {
  width: 100%;
  height: 160px;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
}
.guide-card-body { padding: 18px 20px 20px; }
.guide-card-body h4 { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.guide-card-body p { font-size: 14px; color: var(--color-text-secondary); }

/* --- Grid Layouts --- */
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }

/* --- Responsive --- */
@media (max-width: 1024px) {
  .section { padding: 56px 0; }
  .section-tight { padding: 32px 0; }
}

@media (max-width: 768px) {
  .section { padding: 40px 0; }
  .section-tight { padding: 24px 0; }

  .grid-2, .grid-3 { grid-template-columns: 1fr; }

  .hero { padding: 48px 0; }
  .hero h1 { font-size: 40px; }
  .hero p { font-size: 17px; }

  .product-tile { min-height: 380px; }
  .product-tile-content { padding: 32px 20px; }
  .product-tile-img { height: 160px; font-size: 56px; }

  .carousel-btn { width: 36px; height: 36px; font-size: 16px; }
  .carousel-prev { left: -4px; }
  .carousel-next { right: -4px; }

  .brand-collab { flex-direction: column; text-align: center; gap: 32px; padding: 40px 24px; }

  .promo-banner { flex-direction: column; text-align: center; }

  /* Footer accordion */
  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col h5 { display: none; }
  .footer-col-toggle { display: block; }
  .footer-col ul { display: none; padding-bottom: 8px; }
  .footer-col.open ul { display: block; }

  .section-nav-inner { justify-content: flex-start; }
}

@media (max-width: 480px) {
  .nav-inner { padding: 0 16px; }
  .nav-links { gap: 16px; }
  .nav-links a { font-size: 13px; }

  .container, .container-wide { padding: 0 16px; }

  .product-card { width: 240px; }
  .product-card-img { height: 160px; font-size: 48px; }

  .info-card { width: 240px; padding: 20px 18px; }
  .guide-card { width: 240px; }
  .ent-card { width: 180px; }
  .ent-card-img { height: 220px; }

  .tab-btn { padding: 8px 14px; font-size: 13px; }

  .quick-links { flex-direction: column; }
  .quick-link { text-align: center; }
}

