507	}
508	
509	/* --- Quick Links --- */
510	.quick-links {
511	  display: flex;
512	  gap: 12px;
513	  flex-wrap: wrap;
514	}
515	.quick-link {
516	  padding: 14px 24px;
517	  background: var(--color-white);
518	  border: 1px solid var(--color-border);
519	  border-radius: 980px;
520	  font-size: 15px;
521	  font-weight: 500;
522	  color: var(--color-primary);
523	  cursor: pointer;
524	  transition: all var(--transition);
525	}
526	.quick-link:hover { background: var(--color-bg); border-color: var(--color-primary); }
527	
528	/* --- Sticky Section Nav --- */
529	.section-nav {
530	  position: sticky;
531	  top: 52px;
532	  z-index: 50;
533	  background: rgba(255,255,255,0.92);
534	  backdrop-filter: saturate(180%) blur(20px);
535	  -webkit-backdrop-filter: saturate(180%) blur(20px);
536	  border-bottom: 1px solid var(--color-border);
537	}
538	.section-nav-inner {
539	  max-width: 1200px;
540	  margin: 0 auto;
541	  padding: 0 24px;
542	  display: flex;
543	  gap: 0;
544	  overflow-x: auto;
545	  scrollbar-width: none;
546	}
547	.section-nav-inner::-webkit-scrollbar { display: none; }
548	.section-nav-link {
549	  padding: 14px 20px;
550	  font-size: 14px;
551	  font-weight: 500;
552	  color: var(--color-text-secondary);
553	  white-space: nowrap;
554	  cursor: pointer;
555	  border-bottom: 2px solid transparent;
556	  transition: all var(--transition);
557	  background: none;
558	  border-top: none;
559	  border-left: none;
560	  border-right: none;
561	  font-family: var(--font-stack);
562	}
563	.section-nav-link:hover { color: var(--color-primary); }
564	.section-nav-link.active {
565	  color: var(--color-primary);
566	  border-bottom-color: var(--color-primary);
567	}
568	
569	/* --- Footer --- */
570	.footer {
571	  background: var(--color-bg);
572	  padding: 56px 0 32px;
573	  font-size: 12px;
574	  color: var(--color-text-secondary);
575	}
576	.footer-grid {
577	  display: grid;
578	  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
579	  gap: 32px;
580	  padding-bottom: 32px;
581	  border-bottom: 1px solid var(--color-border);
582	}
583	.footer-col h5 {
584	  font-size: 12px;
585	  font-weight: 600;
586	  color: var(--color-primary);
587	  margin-bottom: 10px;
588	  cursor: default;
589	}
590	.footer-col ul { list-style: none; }
591	.footer-col li { margin-bottom: 6px; }
592	.footer-col a {
593	  font-size: 12px;
594	  color: var(--color-text-secondary);
595	  transition: color var(--transition);
596	}
597	.footer-col a:hover { color: var(--color-primary); text-decoration: underline; }
598	.footer-bottom {
599	  padding-top: 24px;
600	  font-size: 12px;
601	  line-height: 1.6;
602	}
603	.footer-bottom p { margin-bottom: 8px; }
604	.footer-bottom a { color: var(--color-accent); }
605	
606	/* Mobile footer accordion */
607	.footer-col-toggle {
608	  display: none;
609	  width: 100%;
610	  background: none;
611	  border: none;
612	  text-align: left;
613	  padding: 10px 0;
614	  cursor: pointer;
615	  font-size: 12px;
616	  font-weight: 600;
617	  color: var(--color-primary);
618	  font-family: var(--font-stack);
619	}
620	.footer-col-toggle::after {
621	  content: '+';
622	  float: right;
623	  font-size: 14px;
624	  transition: transform var(--transition);
625	}
626	.footer-col-toggle.open::after { content: '−'; }
627	
628	/* --- Category Hero --- */
629	.category-hero {
630	  background: var(--color-bg);
631	  padding: 60px 0;
632	  text-align: center;
633	}
634	.category-hero h1 {
635	  font-size: clamp(40px, 5vw, 56px);
636	  font-weight: 700;
637	  letter-spacing: -0.005em;
638	}
639	
640	/* --- Shopping Guides --- */
641	.guide-card {
642	  width: 280px;
643	  background: var(--color-white);
644	  border-radius: var(--radius-lg);
645	  overflow: hidden;
646	  box-shadow: var(--shadow-sm);
647	  transition: all var(--transition);
648	  flex-shrink: 0;
649	  cursor: pointer;
650	}
651	.guide-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
652	.guide-card-img {
653	  width: 100%;
654	  height: 160px;
655	  background: var(--color-bg);
656	  display: flex;
657	  align-items: center;
658	  justify-content: center;
659	  font-size: 48px;
660	}
661	.guide-card-body { padding: 18px 20px 20px; }
662	.guide-card-body h4 { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
663	.guide-card-body p { font-size: 14px; color: var(--color-text-secondary); }
664	
665	/* --- Grid Layouts --- */
666	.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
667	.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
668	
669	/* --- Responsive --- */
670	@media (max-width: 1024px) {
671	  .section { padding: 56px 0; }
672	  .section-tight { padding: 32px 0; }
673	}
674	
675	@media (max-width: 768px) {
676	  .section { padding: 40px 0; }
677	  .section-tight { padding: 24px 0; }
678	
679	  .grid-2, .grid-3 { grid-template-columns: 1fr; }
680	
681	  .hero { padding: 48px 0; }
682	  .hero h1 { font-size: 40px; }
683	  .hero p { font-size: 17px; }
684	
685	  .product-tile { min-height: 380px; }
686	  .product-tile-content { padding: 32px 20px; }
687	  .product-tile-img { height: 160px; font-size: 56px; }
688	
689	  .carousel-btn { width: 36px; height: 36px; font-size: 16px; }
690	  .carousel-prev { left: -4px; }
691	  .carousel-next { right: -4px; }
692	
693	  .brand-collab { flex-direction: column; text-align: center; gap: 32px; padding: 40px 24px; }
694	
695	  .promo-banner { flex-direction: column; text-align: center; }
696	
697	  /* Footer accordion */
698	  .footer-grid { grid-template-columns: 1fr; gap: 0; }
699	  .footer-col h5 { display: none; }
700	  .footer-col-toggle { display: block; }
701	  .footer-col ul { display: none; padding-bottom: 8px; }
702	  .footer-col.open ul { display: block; }
703	
704	  .section-nav-inner { justify-content: flex-start; }
705	}
706	
707	@media (max-width: 480px) {
708	  .nav-inner { padding: 0 16px; }
709	  .nav-links { gap: 16px; }
710	  .nav-links a { font-size: 13px; }
711	
712	  .container, .container-wide { padding: 0 16px; }
713	
714	  .product-card { width: 240px; }
715	  .product-card-img { height: 160px; font-size: 48px; }
716	
717	  .info-card { width: 240px; padding: 20px 18px; }
718	  .guide-card { width: 240px; }
719	  .ent-card { width: 180px; }
720	  .ent-card-img { height: 220px; }
721	
722	  .tab-btn { padding: 8px 14px; font-size: 13px; }
723	
724	  .quick-links { flex-direction: column; }
725	  .quick-link { text-align: center; }
726	}
